/// 菜单栏菜单的文字。菜单每次打开时重建，语言切换后不用另外刷新。
pub trait MenuStrings: Sync {
    /// 「全部隐藏」打开时显示的菜单项：显示全部缩略图。
    fn show_all(&self) -> &'static str;
    /// 「全部隐藏」关闭时显示的菜单项：隐藏全部缩略图。
    fn hide_all(&self) -> &'static str;
    /// 「配置方案」子菜单的标题。
    fn profiles(&self) -> &'static str;
    /// 把全部 EVE 客户端窗口最小化的菜单项。
    fn minimize_all(&self) -> &'static str;
    /// 打开设置窗口的菜单项，以省略号结尾（macOS 的约定：点了会打开窗口）。
    fn settings(&self) -> &'static str;
    /// 退出本应用的菜单项。
    fn quit(&self) -> &'static str;
    /// 缺少系统权限时出现的菜单项，点击后打开设置窗口的权限页。
    fn permissions_missing(&self) -> &'static str;
    /// 演示模式下菜单顶部的提示行（不可点击）。
    fn fake_mode(&self) -> &'static str;
    /// 没有发现任何 EVE 客户端时菜单顶部的提示行。
    fn no_clients(&self) -> &'static str;
    /// 「恢复捕获」菜单项，后面接客户端的窗口标题。
    fn resume_capture(&self, title: &str) -> String;
    /// 菜单顶部的客户端数量，如「3 个客户端」。俄语按数字选复数形式。
    fn client_count(&self, count: i64) -> String;
    /// 带勾选的菜单项：显示预警浮窗（docs/macos/design-intel-translate.md 第 10 节、第 11 节）。
    fn show_intel_overlay(&self) -> &'static str;
    /// 带勾选的菜单项：显示翻译浮窗。
    fn show_translation_overlay(&self) -> &'static str;
}

