/// 缩略图的右键菜单与占位文字。右键菜单每次打开时新建；占位文字在每次重算时重新设置。
pub trait ThumbnailStrings: Sync {
    /// 最小化这个客户端的窗口。
    fn minimize(&self) -> &'static str;
    /// 最小化全部客户端的窗口。
    fn minimize_all(&self) -> &'static str;
    /// 循环切换时跳过这个角色（勾选项，只在本次运行有效）。
    fn skip_cycle(&self) -> &'static str;
    /// 隐藏这个角色的缩略图（对应客户端页的「显示缩略图」开关）。
    fn hide(&self) -> &'static str;
    /// 恢复默认尺寸。
    fn reset_size(&self) -> &'static str;
    /// 捕获停止后重新开始捕获。
    fn resume_capture(&self) -> &'static str;
    /// 缺少辅助功能权限的说明，接在不可用的菜单项后面，也用在热键问题提示里。
    fn needs_accessibility(&self) -> &'static str;
    /// 菜单项不可用时在后面附上原因，如「最小化（需要辅助功能权限）」。括号写法随语言：中日文用全角括号，其他语言用半角括号加空格。
    fn unavailable(&self, item: &str, reason: &str) -> String;
    /// 打开设置窗口。
    fn settings(&self) -> &'static str;
    /// 已建捕获会话，还没收到第一帧。
    fn waiting(&self) -> &'static str;
    /// 没有屏幕录制权限，拿不到画面。
    fn needs_screen_recording(&self) -> &'static str;
    /// 捕获出错停止，提示用户用右键菜单恢复。
    fn capture_stopped(&self) -> &'static str;
    /// 客户端窗口已最小化。
    fn minimized(&self) -> &'static str;
    /// Windows：缩略图上的占位文字，系统给不出这个窗口的画面（DWM 缩略图注册失败）。
    fn preview_unavailable(&self) -> &'static str;
}

